-- 40 more unique Rockmundo-specific media interview questions; safely replayable.
WITH seed(category,media_types,question_text,a,b,c,d) AS (VALUES
('education_learning',ARRAY['podcast','magazine','newspaper']::text[],'Has studying music theory changed the way you write songs?','It gives me more ways to express the emotion I hear.','I use theory when it helps, then trust my ears.','Learning the rules gave me more interesting ways to break them.','Now I can explain exactly why my favourite chord sounds odd.'),
('education_learning',ARRAY['radio','podcast','tv']::text[],'What''s the hardest musical skill you''ve tried to learn recently?','Keeping a steady rhythm while learning a new technique.','I break difficult skills into smaller daily exercises.','I tackle the thing I''m worst at rather than hiding from it.','My fingers keep voting against the new exercise.'),
('education_learning',ARRAY['podcast','magazine']::text[],'Can watching lessons online replace working with a good teacher?','Online lessons are great for getting started and exploring ideas.','Personal feedback catches habits a video can''t notice.','I''ll learn from anywhere as long as it makes me better.','A video never tells me to practise the boring bit twice.'),
('education_learning',ARRAY['podcast','magazine','newspaper']::text[],'What would make you travel to another city for a masterclass?','The chance to learn directly from someone I admire.','I''d look at the teaching quality, timing and travel costs.','One brilliant mentor could change how I approach music.','I hope they provide a map and a working practice room.'),
('education_learning',ARRAY['all']::text[],'How do you make sure regular practice doesn''t become a chore?','I connect exercises to music I genuinely want to play.','Short, focused sessions help me keep improving.','I challenge myself with something that feels almost impossible.','I set a timer before the scales start negotiating.'),
('education_learning',ARRAY['podcast','magazine','radio']::text[],'Would you rather master your main instrument or learn three new ones?','Deep mastery lets me express more with every note.','I''d focus on my main instrument while exploring others slowly.','I want a whole wall of instruments I can actually play.','My band would prefer I master tuning just one.'),
('education_learning',ARRAY['podcast','magazine','newspaper']::text[],'What do you learn from reading about legendary musicians?','Their struggles remind me that great music takes persistence.','I look for practical habits I can adapt to my own career.','The best stories inspire me to risk sounding different.','I learned even legends lose guitar picks.'),
('education_learning',ARRAY['radio','tv','podcast']::text[],'Could a visiting professor change the direction of your next album?','A new perspective might unlock songs we hadn''t imagined.','We''d experiment with the ideas before choosing a direction.','I''d let a remarkable teacher push us out of our comfort zone.','I hope they don''t assign an essay before soundcheck.'),
('education_learning',ARRAY['podcast','magazine','newspaper']::text[],'How do you know when you''ve genuinely mastered a skill?','When I can use it naturally in a real performance.','Consistent results under pressure matter more than a certificate.','Mastery means being able to improvise rather than repeat drills.','When I can play it while the drummer makes faces at me.'),
('education_learning',ARRAY['radio','podcast','tv']::text[],'Would you ever teach a beginner musician during a tour stop?','Yes, passing on what I''ve learned would be rewarding.','I''d make time if we could organise it responsibly.','Imagine a local beginner joining us for a song on stage.','I''d teach them the riff before anyone mentions music theory.'),
('festival_management',ARRAY['magazine','newspaper','podcast']::text[],'What makes a festival worth returning to year after year?','The atmosphere and the way performers and fans are treated.','Reliable organisation and fair terms make a huge difference.','A festival with a distinct character beats another identical lineup.','Working toilets earn an immediate return invitation.'),
('festival_management',ARRAY['radio','tv','podcast']::text[],'Would you rather headline a small festival or play mid-bill at a giant one?','A small headline set lets us build something special.','I''d compare the audience, slot and long-term opportunity.','I''d take the giant crowd and make them remember our name.','Whichever stage has the better view of the food stalls.'),
('festival_management',ARRAY['podcast','magazine','newspaper']::text[],'How important is a festival''s running order to the crowd''s experience?','A well-paced lineup can take the audience on a journey.','Different genres and crowd sizes need thoughtful scheduling.','Put a surprising act between favourites and watch the field wake up.','Don''t schedule the quiet acoustic set beside the fireworks.'),
('festival_management',ARRAY['magazine','newspaper','podcast']::text[],'Should festival organisers publish ticket sales and lineup updates?','Clear communication builds trust with both fans and artists.','Share useful information without exposing private contracts.','If plans change, the crowd deserves to hear it promptly.','Just don''t announce a secret headliner before telling them.'),
('festival_management',ARRAY['all']::text[],'What would persuade you to accept a late festival invitation?','If we could prepare a great show without letting anyone down.','I''d check transport, crew availability and the technical setup.','A last-minute crowd can bring out our most fearless performance.','First tell me how far away the stage is.'),
('festival_management',ARRAY['magazine','newspaper','podcast']::text[],'Should city festivals use local businesses and suppliers?','Yes, the surrounding community should benefit from the event.','Local suppliers can bring value if standards remain consistent.','A festival should feel rooted in its city, not shipped in a box.','And someone local usually knows where to find proper food.'),
('festival_management',ARRAY['radio','podcast','magazine']::text[],'How would you react to being moved from the main stage to a smaller one?','I''d give the same effort to everyone who came to watch us.','I''d want a clear explanation and fair revised arrangements.','I''d turn the smaller stage into the loudest part of the site.','As long as the drum kit fits through the door.'),
('festival_management',ARRAY['magazine','newspaper','podcast']::text[],'Is offering fair pay to opening acts essential for a good festival?','Absolutely, new artists have bills just like headliners.','Organisers should budget honestly for every slot.','A festival built on unpaid talent has its priorities wrong.','Exposure doesn''t put fuel in the van.'),
('festival_management',ARRAY['radio','tv','podcast']::text[],'Could playing a festival abroad change your band''s sound?','Experiencing new scenes always broadens our perspective.','We''d listen and learn without borrowing carelessly.','A foreign festival could spark a completely new record.','Only if we find the venue before the set begins.'),
('festival_management',ARRAY['podcast','magazine','newspaper']::text[],'What makes a festival sponsor a good fit for your band?','The brand should share values we can stand behind.','We''d assess how the partnership affects the show and our fans.','I''d rather reject a big cheque than make a fake endorsement.','If the sponsor insists on naming every guitar solo, no thanks.'),
('performance_stage',ARRAY['radio','tv','podcast']::text[],'How much attention do you give to camera angles at a huge concert?','Good cameras can help distant fans see the emotion.','We coordinate with production without losing the live feeling.','A dramatic camera moment can make the whole show cinematic.','Please don''t zoom in when I''m changing a broken string.'),
('performance_stage',ARRAY['radio','tv','podcast']::text[],'Would you change the lighting design to suit one dramatic song?','Absolutely, light can change how a song feels.','We''d design cues that work safely with the venue.','I''d turn the whole stage dark before the final chorus hits.','My dream cue is one that doesn''t blind the drummer.'),
('performance_stage',ARRAY['podcast','magazine','newspaper']::text[],'Is a seated audience harder to win over than a standing crowd?','Connection matters whether people are seated or standing.','I''d adapt the pacing without assuming they aren''t enjoying it.','The challenge is making everyone feel the energy in their seat.','At least nobody needs to stand on someone else''s toes.'),
('performance_stage',ARRAY['radio','tv','podcast']::text[],'What do you do when the crowd sings louder than your monitors?','I let them have their moment and sing along.','We keep the tempo steady and enjoy the response.','I stop singing for a bar just to hear the whole room.','I check the microphone hasn''t quietly retired.'),
('performance_stage',ARRAY['podcast','magazine','newspaper']::text[],'Would you invite a fan on stage for a song?','Only when we can do it safely and make it meaningful.','We''d coordinate it with security and the stage team.','A fan playing the final chorus could be unforgettable.','They might know the words better than I do.'),
('performance_stage',ARRAY['radio','tv','podcast']::text[],'Would you ever perform a full set without screens or effects?','Yes, strong songs should stand on their own.','An intimate show can use a simpler production design.','Stripping everything back could be our boldest live statement.','I''d still like one working microphone.'),
('performance_stage',ARRAY['podcast','magazine','radio']::text[],'How do you recover when an instrument fails mid-song?','We keep the rhythm and help each other through it.','Good crew preparation makes swaps quick and safe.','An unexpected breakdown can become a brilliant improvised moment.','I pretend the silence was part of the arrangement.'),
('performance_stage',ARRAY['magazine','newspaper','podcast']::text[],'Should concert reviews judge production separately from the musicians?','Yes, the music and the staging are different crafts.','I''d welcome detailed feedback on both elements.','A spectacular stage can''t hide an uninspired performance.','I hope they don''t give the smoke machine a solo credit.'),
('performance_stage',ARRAY['radio','podcast','tv']::text[],'What''s your favourite way to surprise a crowd during an encore?','Bring back a song fans never expected to hear.','We plan a few possibilities and read the room.','I''d invite another act out for an unannounced collaboration.','Sometimes just playing the encore on time is a surprise.'),
('performance_stage',ARRAY['podcast','magazine','newspaper']::text[],'Would you rather have flawless sound or an extraordinary stage spectacle?','I''d choose sound that lets people hear the songs clearly.','I''d seek a balance because both affect the experience.','A wild spectacle is worth it only if the music survives.','Give me working monitors before you order a laser dragon.'),
('world_cities',ARRAY['magazine','newspaper','podcast']::text[],'How does a city''s local music scene shape your experience on tour?','Local musicians often show us the heart of a city.','We try to meet promoters and artists instead of only seeing venues.','A vibrant scene can inspire an entirely new song.','My favourite guide is usually the person selling records nearby.'),
('world_cities',ARRAY['podcast','magazine','newspaper']::text[],'Could investment in music venues transform a struggling city?','Yes, places to perform bring communities together.','Improved facilities need sustainable funding and good management.','A thriving venue circuit can put a city on the music map.','Start with decent stages and toilets that actually work.'),
('world_cities',ARRAY['magazine','newspaper','podcast']::text[],'Should city mayors have a say in local music festivals?','They should support events that benefit local residents.','Clear rules and budgets help festivals survive.','I''d love a mayor who actively champions emerging performers.','As long as they don''t choose the band''s outfits.'),
('world_cities',ARRAY['radio','podcast','magazine']::text[],'Do you notice differences between audiences in different countries?','Every crowd has its own rhythm and traditions.','We adapt how we talk to fans while keeping our identity.','The surprises are what make international touring exciting.','I mainly notice how differently they cheer for encores.'),
('world_cities',ARRAY['podcast','magazine','newspaper']::text[],'What''s the best way for a small city to attract touring bands?','Build reliable venues and treat visiting musicians fairly.','Good transport links and sensible booking fees help.','Make it the town where every band has an incredible night.','And tell bands where they can park the van.'),
('world_cities',ARRAY['radio','podcast','tv']::text[],'Have local markets ever inspired a song or a stage outfit?','Exploring local crafts and food can spark unexpected ideas.','We collect details from each city and use what fits.','One strange market find could become our next iconic costume.','I once found a jacket louder than our amplifiers.'),
('world_cities',ARRAY['magazine','newspaper','podcast']::text[],'Should a band''s fame in one country guarantee success elsewhere?','Every audience deserves to discover music in its own way.','We''d build local relationships rather than assume instant demand.','I''d happily start again in tiny clubs to win a new country.','A sold-out gig at home doesn''t teach me another language.'),
('world_cities',ARRAY['radio','tv','podcast']::text[],'Would you play an intimate show in a city that usually books you into arenas?','Absolutely, smaller rooms create a special connection.','We''d make sure the ticketing is fair and accessible.','I''d love to see an arena band tear up a 300-capacity room.','It would be nice to find the dressing room without a map.'),
('world_cities',ARRAY['podcast','magazine','newspaper']::text[],'How important are local record shops to a music community?','They give fans and artists a place to meet and discover music.','They can thrive by supporting local releases and events.','A great record shop keeps a city''s musical memory alive.','I always buy more records than my luggage allowance allows.'),
('world_cities',ARRAY['magazine','newspaper','podcast']::text[],'What should a city prioritise before announcing a major concert event?','Safety, accessible transport and respect for local residents.','A realistic budget and experienced organisers come first.','Make the event ambitious, but don''t overpromise the experience.','And perhaps warn the neighbours about our drummer.')
), inserted AS (
INSERT INTO public.interview_questions
(category,media_types,question_text,option_a_text,option_a_effects,option_b_text,option_b_effects,option_c_text,option_c_effects,option_d_text,option_d_effects)
SELECT s.category,s.media_types,s.question_text,
s.a,jsonb_build_object('fame_mult',1.03,'fan_mult',1.04,'cash_mult',1.00,'reputation',jsonb_build_object('authentic',2,'professional',1)),
s.b,jsonb_build_object('fame_mult',1.01,'fan_mult',1.02,'cash_mult',1.02,'reputation',jsonb_build_object('diplomatic',2,'professional',2)),
s.c,jsonb_build_object('fame_mult',1.05,'fan_mult',0.99,'cash_mult',0.99,'reputation',jsonb_build_object('bold',2,'rebellious',2)),
s.d,jsonb_build_object('fame_mult',1.02,'fan_mult',1.01,'cash_mult',1.00,'reputation',jsonb_build_object('unpredictable',2,'authentic',1))
FROM seed s WHERE NOT EXISTS (SELECT 1 FROM public.interview_questions q WHERE lower(btrim(q.question_text))=lower(btrim(s.question_text)))
RETURNING id
) SELECT count(*)::integer AS inserted_count FROM inserted;